assignments.value:
={{ (() => {
  const body = $('Webhook (Portafolio Coach IA)').first().json.body || {};
  const errors = [];
  if (body.source !== 'siga_portfolio_studio') errors.push({ field: 'source', message: 'Origen inválido' });
  if (body.mode !== 'coach' && body.mode !== 'import_pdf') errors.push({ field: 'mode', message: 'mode debe ser coach o import_pdf' });
  if (body.mode === 'coach') {
    const msg = typeof body.message === 'string' ? body.message.trim() : '';
    if (msg.length < 2 || msg.length > 1000) errors.push({ field: 'message', message: 'Mensaje entre 2 y 1000 caracteres requerido' });
  }
  if (body.mode === 'import_pdf') {
    const txt = typeof body.extracted_text === 'string' ? body.extracted_text.trim() : '';
    if (txt.length < 40 || txt.length > 14000) errors.push({ field: 'extracted_text', message: 'Texto extraído de PDF entre 40 y 14000 caracteres requerido' });
  }
  return { valid: errors.length === 0, validationError: errors.length > 0 ? 'Solicitud inválida.' : null, details: errors };
})() }}

