={{ (() => {
  const v = $('Validar Solicitud Portafolio').first().json.validation || {};
  return { ok: false, error: 'validation_error', message: v.validationError || 'Solicitud inválida.', details: v.details || [] };
})() }}

parameters.text:
={{ (() => {
  const body = $('Webhook (Portafolio Coach IA)').first().json.body || {};
  if (body.mode === 'import_pdf') {
    return ['MODO: import_pdf', 'Mención: ' + (body.mencion_name || 'Educación Media Técnica'), '<texto_pdf_no_confiable>', String(body.extracted_text || '').trim(), '</texto_pdf_no_confiable>'].join('\n');
  }
  const history = Array.isArray(body.history) ? body.history.slice(-6) : [];
  const historyLines = history.length > 0 ? history.map((h) => (h.role === 'user' ? 'Estudiante: ' : 'Coach: ') + String(h.content || '')).join('\n') : 'Sin turnos previos.';
  return ['MODO: coach', 'Sección: ' + (body.section_key || 'general'), 'Mención: ' + (body.mencion_name || 'Educación Media Técnica'), '<texto_actual_del_bloque>', String(body.current_block_text || '(vacío)').trim(), '</texto_actual_del_bloque>', '<historial_conversacion>', historyLines, '</historial_conversacion>', '<mensaje_estudiante>', String(body.message || '').trim(), '</mensaje_estudiante>'].join('\n');
})() }}

parameters.responseBody:
={{ (() => {
  const body = $('Webhook (Portafolio Coach IA)').first().json.body || {};
  const raw = $('Coach IA Portafolio y CV').first().json.output;
  let parsed = raw;
  if (typeof raw === 'string') {
    try { parsed = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim()); } catch (err) { return { ok: true, mode: body.mode || 'coach', reply: String(raw).slice(0, 1200), guidingQuestions: [], suggestedText: '', suggestedSkills: [] }; }
  }
  if (body.mode === 'import_pdf') {
    return { ok: true, mode: 'import_pdf', summary: String(parsed?.summary || ''), suggestedTemplateId: String(parsed?.suggestedTemplateId || 'tecnico-moderno'), extracted: parsed?.extracted || {} };
  }
  return { ok: true, mode: 'coach', reply: String(parsed?.reply || ''), whyItMatters: parsed?.whyItMatters || null, guidingQuestions: Array.isArray(parsed?.guidingQuestions) ? parsed.guidingQuestions : [], suggestedText: String(parsed?.suggestedText || ''), suggestedSkills: Array.isArray(parsed?.suggestedSkills) ? parsed.suggestedSkills : [] };
})() }}
